nta.declaration:
// Small network test, separate from the full mission/command model.
// One time unit is 100 ms here. These are example values, not MAVLink defaults.
const int N_PRODUCERS = 2;
const int N_ENDPOINTS = 2;
const int PACKETS_PER_PRODUCER = 2;
const int N_PACKETS = N_PRODUCERS * PACKETS_PER_PRODUCER;
const int D_MIN = 1;
const int D_MAX = 5;
// 0 = reliable, 1 = any packet can be lost, 2 = bounded consecutive losses
const int LOSS_MODE = 0;
const int K_LOSS = 1;

typedef int[0,N_PRODUCERS-1] producer_id;
typedef int[0,N_ENDPOINTS-1] endpoint_id;
typedef int[0,N_PACKETS-1] packet_id;
typedef int[0,1] kind_id;
typedef int[0,9] payload_t;
typedef struct { packet_id id; endpoint_id src; endpoint_id dst;
                 kind_id kind; payload_t payload; } packet_t;

// Each producer has its own place to put a packet while it waits.
packet_t outgoing[N_PRODUCERS];
packet_t incoming;
urgent chan net_tx[N_PRODUCERS];
chan net_rx[N_ENDPOINTS];

// Harness bookkeeping. IDs are used once, they are not MAVLink fields.
// 0 = not admitted, 1 = in flight, 2 = delivered, 3 = lost
int[0,3] status[N_PACKETS];
packet_t expected[N_PACKETS];
int[0,2] deliveries[N_PACKETS];
bool integrityError = false;
bool pending[N_PRODUCERS];
int[0,K_LOSS] consecutiveLoss[N_PRODUCERS];
int[0,N_PACKETS] admitted = 0;
int[0,N_PACKETS] delivered = 0;
int[0,N_PACKETS] lost = 0;

template.declaration:
clock x;
packet_t packet;
producer_id owner = 0;

nta.system:
Link = Network();
Sender0 = Producer(0);
Sender1 = Producer(1);
Receiver0 = Receiver(0);
Receiver1 = Receiver(1);
system Link, Sender0, Sender1, Receiver0, Receiver1;
